SELECT  FROM sol_site_survey
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND deleted=0 AND status IN (0,1,3)
AND id > #{query.afterId}
ORDER BY id LIMIT #{query.limit}

SELECT  FROM sol_site_survey
WHERE tenant_id = #{query.tenantId} AND project_id = #{query.projectId} AND deleted = 0
ORDER BY id DESC LIMIT #{query.limit}

mapper.update:
UPDATE sol_site_survey SET deleted = 1, version = version + 1, update_time = CURRENT_TIMESTAMP
WHERE id = #{query.id} AND tenant_id = #{query.tenantId} AND version = #{query.version}
  AND status = 0 AND deleted = 0 AND outsource_request_id IS NULL
